function setupGameInfo(t){const e=document.getElementById("lottery-game-info");e.querySelector(".lottery-game-round-no").textContent=gameContractMeta.curRound,e.querySelector(".lottery-amount").textContent=gameContractMeta.curBonus,document.getElementById("lottery-total-amount").textContent=gameContractMeta.totalBonus,document.getElementById("lottery-current-ticket-amount").textContent=gameContractMeta.ticketNo,document.getElementById("bonus-for-points-value").textContent=gameContractMeta.bonusForPoint}function setCounterInfo(t,e,n,o,r){t.querySelector(".days").textContent=e,t.querySelector(".hours").textContent=n,t.querySelector(".minutes").textContent=o,t.querySelector(".seconds").textContent=r}function initTimerOfCounterDown(){let t=0;resetCounter(gameContractMeta.dTime),startCountdown((async function(e,n,o,r,i){const s=document.getElementById("lottery-count-down"),a=document.getElementById("countdown-result-parent");i?(a.style.display="block",s.style.display="none"):(s.style.display="flex",a.style.display="none",setCounterInfo(s,e,n,o,r)),t+=1,t<TimeIntervalForBlockChain||(t=0,await initGameContractMeta(),resetCounter(gameContractMeta.dTime),setupGameInfo())}))}function calculateAnnualYield(t,e){if(t<=0||e<=0)return 0;return 365*(3*(100*(t/e*.2)))}async function loadUserPointsInfos(){const t=await GetToSrvByJson("/pointsForNJUsr?web3_id="+ninjaUserObj.eth_addr.toLowerCase());if(!t)return;if(document.getElementById("dessage-web3-token").innerText=t.points.toFixed(2),document.getElementById("dessage-token-bonus").innerText=t.bonus_to_win.toFixed(2),t.points<=0||t.snapshot_points<=0||t.cur_total_points<=0)return;const e=t.snapshot_points*pointBonusOneRound/t.cur_total_points,n=3*pointBonusOneRound*365*100/t.cur_total_points;document.getElementById("point-bonus-this-round").innerText=e.toFixed(2),document.getElementById("point-bonus-annual-interest").innerText=n.toFixed(2)+"%"}function showSelfReferralCode(){document.getElementById("referral-Code-info").style.display="block"}function copyReferralCode(){navigator.clipboard.writeText(this.innerText).then((function(){document.getElementById("referral-Code-info").style.display="none",showTmpTips("Copy Success")})).catch((function(t){console.error("Failed to copy the text: ",t),showTmpTips("Copy Failed")}))}function copyRecommenderCode(){const t=document.getElementById("user-setting-referrer-val");t.innerText&&navigator.clipboard.writeText(t.innerText).then((function(){showTmpTips("Copy Success")})).catch((function(t){console.error("Failed to copy the text: ",t),showTmpTips("Copy Failed")}))}